<template>
  <el-container v-if="vipInfo">
    <el-header class="home-header">
      <vr-header />
    </el-header>
    <div class="header">
      <img :src="vipInfo.company_banner_cover" :alt="vipInfo.nickname" class="header-bg" />
      <div class="profile-picture">
        <img :src="vipInfo.avatar_full" :alt="vipInfo.nickname" />
        <div class="avatar-edit" @click="editInfo('avatar')">修改头像</div>
      </div>
    </div>
    <div class="content">
      <div class="profile-name">{{ vipInfo.nickname }}</div>
      <div class="section">
        <h2>个人信息</h2>
        <div class="info">
          <div class="info-item">
            <span>账号ID:</span> <span>{{ vipInfo.uuid }}</span>
          </div>
          <div class="info-item">
            <span>用户名: </span><span>{{ vipInfo.nickname }}</span>
            <a href="#" @click="editInfo('nickname')"><b>编辑</b></a>
          </div>
          <div class="info-item">
            <span>简介:</span>
            <span class="intro">{{
              vipInfo.intro ? vipInfo.intro : "暂无"
            }}</span>
            <a href="#" @click="editInfo('intro')">
              <b>编辑</b>
            </a>
          </div>
          <div class="info-item">
            <span>注册时间: </span
            ><span>{{
              vipInfo.createdTime | timeFormatFilter("yyyy-MM-DD")
            }}</span>
          </div>
          <div class="info-item">
            <span>用户身份: </span>
            <span>{{ vipInfo.role_text }}</span>
            <a v-if="vipInfo.role == 0" href="#" @click="upgradeRole">
              <b v-if="vipInfo.company && parseInt(vipInfo.company.status) !== 1">企业认证中</b>
              <b v-else>企业认证</b>
            </a>
            <a v-else href="#" @click="showCompanyInfo"><b>企业信息</b></a>
          </div>
        </div>
      </div>
      <div class="section">
        <h2>账号安全</h2>
        <div class="info">
          <div class="info-item">
            <span>手机号: </span
            ><span>{{ vipInfo.phone ? vipInfo.phone : "未绑定" }}</span>
            <a href="#" @click="editInfo('phone')">
              <b v-if="!vipInfo.phone">立即绑定</b>
              <b v-else>修改绑定</b>
            </a>
          </div>
          <div class="info-item">
            <span>邮箱号: </span
            ><span>{{ vipInfo.email ? vipInfo.email : "未绑定" }}</span>
            <a href="#" @click="editInfo('email')">
              <b v-if="!vipInfo.email">立即绑定</b>
              <b v-else>修改绑定</b>
            </a>
          </div>
          <!-- <div class="info-item">
            <span>微信状态: </span><span>未绑定</span> <a href="#">解除绑定</a>
          </div> -->
          <div class="info-item">
            <span>账号密码: </span><span>***</span> <a href="#" @click="editInfo('password')"><b>修改密码</b></a>
          </div>
        </div>
      </div>
    </div>
    <form-dialog ref="dialog" @changed="onInfoChange"/>
    <company-form-dialog ref="companyDialog" @ok="onCompanyRegOk"/>
    <company-info-drawer ref="companyInfoDrawer" />
  </el-container>
</template>
  <script>
import { getCurrentUser } from '@/api/user'
import { mapActions } from 'vuex'
export default {
  name: 'VIPInfo',
  components: {
    VrHeader: () => import('../layout/header.vue'),
    FormDialog: () => import('./form.vue'),
    CompanyFormDialog: () => import('./company-form.vue'),
    CompanyInfoDrawer: () => import('./company-info.vue')
  },
  data() {
    return {
      vipInfo: null,
    }
  },
  async created() {
    this.vipInfo = await getCurrentUser()
  },
  methods: {
    ...mapActions('user', ['getCurrentUser', 'logout']),
    editInfo(scene) {
      this.$refs.dialog.open(scene, this.vipInfo)
    },
    async onInfoChange(scene, pwd) {
      this.vipInfo = await getCurrentUser()
      this.getCurrentUser()
      if (scene === 'password' && pwd) {
        await this.logout()
        this.$router.push('/')
      }
    },
    upgradeRole() {
      this.$refs.companyDialog.open(this.vipInfo)
    },
    showCompanyInfo() {
      this.$refs.companyInfoDrawer.open(this.vipInfo)
    },
    onCompanyRegOk() {}
  }
}
</script>
